LEGACY_RECORDS = [{'source': '', 'values': {'showroom_service_tier': 'Standard', 'annual_maintenance_visits': '6', 'vehicle_bay_cleaning_minutes_last_month': '180', 'VehicleID': '1', 'VehicleType': 'Sedans', 'Capacity': '100'}}, {'source': '', 'values': {'showroom_service_tier': 'Priority', 'annual_maintenance_visits': '4', 'vehicle_bay_cleaning_minutes_last_month': '240', 'VehicleID': '2', 'VehicleType': 'SUVs', 'Capacity': '80'}}, {'source': '', 'values': {'showroom_service_tier': 'Priority', 'annual_maintenance_visits': '3', 'vehicle_bay_cleaning_minutes_last_month': '300', 'VehicleID': '3', 'VehicleType': 'Electric Vehicles', 'Capacity': '120'}}, {'source': '', 'values': {'showroom_service_tier': 'Standard', 'annual_maintenance_visits': '2', 'vehicle_bay_cleaning_minutes_last_month': '360', 'VehicleID': '4', 'VehicleType': 'Hybrid Vehicles', 'Capacity': '90'}}, {'source': '', 'values': {'showroom_service_tier': 'Premium', 'annual_maintenance_visits': '3', 'vehicle_bay_cleaning_minutes_last_month': '120', 'VehicleID': '5', 'VehicleType': 'Trucks', 'Capacity': '50'}}, {'source': '', 'values': {'showroom_service_tier': 'Priority', 'annual_maintenance_visits': '4', 'vehicle_bay_cleaning_minutes_last_month': '180', 'VehicleID': '6', 'VehicleType': 'Sports Cars', 'Capacity': '30'}}, {'source': '', 'values': {'showroom_service_tier': 'Priority', 'annual_maintenance_visits': '6', 'vehicle_bay_cleaning_minutes_last_month': '360', 'VehicleID': '7', 'VehicleType': 'Compact Cars', 'Capacity': '110'}}, {'source': '', 'values': {'showroom_service_tier': 'Priority', 'annual_maintenance_visits': '8', 'vehicle_bay_cleaning_minutes_last_month': '240', 'VehicleID': '8', 'VehicleType': 'Luxury Sedans', 'Capacity': '40'}}, {'source': '', 'values': {'showroom_service_tier': 'Standard', 'annual_maintenance_visits': '2', 'vehicle_bay_cleaning_minutes_last_month': '240', 'VehicleID': '9', 'VehicleType': 'Vans', 'Capacity': '60'}}, {'source': '', 'values': {'showroom_service_tier': 'Standard', 'annual_maintenance_visits': '2', 'vehicle_bay_cleaning_minutes_last_month': '240', 'VehicleID': '10', 'VehicleType': 'Pickup Trucks', 'Capacity': '35'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '680', 'warranty_months': '48', 'ProductName': 'Sedans', 'Value': '1200'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '920', 'warranty_months': '48', 'ProductName': 'SUVs', 'Value': '1800'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '920', 'warranty_months': '60', 'ProductName': 'Electric Vehicles', 'Value': '2500'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '680', 'warranty_months': '60', 'ProductName': 'Hybrid Vehicles', 'Value': '2000'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '120', 'warranty_months': '12', 'ProductName': 'Trucks', 'Value': '1500'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '250', 'warranty_months': '36', 'ProductName': 'Sports Cars', 'Value': '3000'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '410', 'warranty_months': '36', 'ProductName': 'Compact Cars', 'Value': '1000'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '120', 'warranty_months': '60', 'ProductName': 'Luxury Sedans', 'Value': '3500'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '120', 'warranty_months': '48', 'ProductName': 'Vans', 'Value': '1600'}}, {'source': '', 'values': {'vehicle_catalog_views_last_month': '250', 'warranty_months': '60', 'ProductName': 'Pickup Trucks', 'Value': '1700'}}]
import gurobipy as gp
from gurobipy import GRB
vehicle_records = [r for r in LEGACY_RECORDS if 'VehicleID' in r['values']]
product_records = [r for r in LEGACY_RECORDS if 'ProductName' in r['values']]
vehicle_types = []
vehicle_ids = []
capacity = {}
for rec in vehicle_records:
    vt = rec['values']['VehicleType']
    vid = rec['values']['VehicleID']
    vehicle_types.append(vt)
    vehicle_ids.append(vid)
    capacity[vt] = int(rec['values']['Capacity'])
benefit = {}
for rec in product_records:
    vt = rec['values']['ProductName']
    benefit[vt] = int(rec['values']['Value'])
if set(vehicle_types) != set(benefit.keys()):
    raise ValueError('Mismatch between vehicle types in capacity and benefit data.')
types = vehicle_types
total_capacity = sum((capacity[vt] for vt in types))
m = gp.Model('Car_Dealership_Inventory')
x = m.addVars(types, lb=0, ub=[capacity[vt] for vt in types], vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((benefit[vt] * x[vt] for vt in types)), GRB.MAXIMIZE)
m.addConstr(gp.quicksum((x[vt] for vt in types)) <= total_capacity, name='total_capacity')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for vt in types:
        print(f'x[{vt}]: {x[vt].X}')
else:
    print(f'Solver status: {m.Status}')